import numpy as np
from scipy.optimize import minimize_scalar
one=np.ones_like(t)
def build(w):
    s=np.sin(w*t);c=np.cos(w*t);sq=np.sqrt(P)
    cols={'1':one,'P':P,'P2':P*P,'sqP':sq,'t':t,'t2':t*t}
    base={}
    for pn,pv in [('1',one),('P',P),('P2',P*P),('sqP',sq)]:
        for tn,tv in [('1',one),('t',t),('t2',t*t),('s',s),('c',c)]:
            base[pn+'*'+tn]=pv*tv
